# -*- coding: utf-8 -*-
"""第 6 章 6.1（下）特征多项式、复特征值、迹与行列式、相似（Leon 9th §6.1：例 3 λ = 4, −3；例 4 p(λ) = −λ(λ − 1)²；
例 5 1 ± 2i；例 6 tr = 4、det = 13；定理 6.1.1；例 7 A = S⁻¹TS = (−1 −2; 6 6)）台词源（唯一真源）。
3B1B 画面：λ 滑块扫过，det(A − λI) 的面积缩放因子穿过 0；旋转放大没有实特征线。
运行：python lines.py → script.json / lines.json
"""
import json
from pathlib import Path

LINES = [
    dict(id='C01', pose='claude_smile', sub='上一节得到特征方程 det(A − λI) = 0。展开后是 λ 的 n 次多项式 p(λ)，叫特征多项式。', read='上一节得到了特征方程。把左边的行列式展开，是拉姆达的n次多项式，叫作特征多项式。'),
    dict(id='C02', pose='claude_explain', sub='例 3：A = (3 2; 3 −2)。det(A − λI) = (3 − λ)(−2 − λ) − 6 = λ² − λ − 12 = (λ − 4)(λ + 3)。', read='例三：A的第一行是三、二，第二行是三、负二。A减拉姆达I的行列式，等于三减拉姆达，乘负二减拉姆达，再减六，整理得拉姆达平方，减拉姆达，减十二，分解成拉姆达减四，乘拉姆达加三。'),
    dict(id='C03', pose='claude_point', sub='所以 λ₁ = 4，λ₂ = −3。λ = 4 时解 (A − 4I)x = 0，得 x = (2, 1)ᵀ；λ = −3 时得 (−1, 3)ᵀ。', read='所以拉姆达一等于四，拉姆达二等于负三。对拉姆达等于四，解A减四I乘x等于零，得到二、一；对负三，得到负一、三。'),
    dict(id='C04', pose='claude_explain', sub='画面上：让 λ 从左往右滑，A − λI 的面积缩放因子跟着变。它穿过零的两个位置，正好是 −3 和 4。', read='看画面：让拉姆达从左往右滑，A减拉姆达I的面积缩放因子跟着变化。它穿过零的那两个位置，正好是负三和四。'),
    dict(id='D01', mood='think', pose='ds_think', sub='三阶的也这样算？要展开三阶行列式？', read='三阶的也这样算？要展开三阶行列式吗？'),
    dict(id='C05', pose='claude_smile', sub='对。例 4：A = (2 −3 1; 1 −2 1; 1 −3 2)，展开得 p(λ) = −λ(λ − 1)²。特征值是 0，以及二重的 1。', read='对。例四是一个三阶矩阵，展开得到，负拉姆达，乘拉姆达减一的平方。特征值是零，以及二重的一。'),
    dict(id='C06', pose='claude_point', sub='λ = 0 的特征空间就是 N(A)，由 (1, 1, 1)ᵀ 张成。λ = 1 时，A − I 三行相同，只剩一个方程 x₁ − 3x₂ + x₃ = 0。', read='拉姆达等于零的特征空间，就是A的零空间，由一、一、一张成。拉姆达等于一的时候，A减I的三行完全相同，只剩一个方程：x一减三x二加x三，等于零。'),
    dict(id='C07', pose='claude_explain', sub='两个自由变量，特征空间是平面，基为 (3, 1, 0)ᵀ 和 (−1, 0, 1)ᵀ。二重根，这里正好配了两个无关的特征向量。', read='两个自由变量，特征空间是一个平面，基是三、一、零，和负一、零、一。二重根，这里正好配了两个无关的特征向量。'),
    dict(id='C08', pose='claude_explain', sub='再看例 5：A = (1 2; −2 1)。p(λ) = (1 − λ)² + 4，没有实根，特征值是 1 + 2i 和 1 − 2i。', read='再看例五：A的第一行是一、二，第二行是负二、一。特征多项式是一减拉姆达的平方加四，没有实根。特征值是一加二i，和一减二i。'),
    dict(id='C09', pose='claude_point', sub='几何上：这个矩阵是旋转再放大，每个向量都被转走了，平面里根本没有不转向的方向。只能到复数里去找。', read='几何上看，这个矩阵是旋转再放大，每个向量都被转走了，平面里根本没有不转向的方向。所以只能到复数里去找。'),
    dict(id='D02', mood='think', pose='ds_confused', sub='复数的特征向量……还能画吗？', read='复数的特征向量，还能画出来吗？'),
    dict(id='C10', pose='claude_smile', sub='画不进平面了，但能算：属于 1 + 2i 的是 (1, i)ᵀ，属于 1 − 2i 的是 (1, −i)ᵀ。实矩阵的复特征值总是共轭成对出现。', read='画不进平面了，但是能算：属于一加二i的特征向量是一、i，属于一减二i的是一、负i。实矩阵的复特征值，总是共轭成对出现。'),
    dict(id='C11', pose='claude_explain', sub='特征多项式还藏着两个性质。写成 p(λ) = (λ₁ − λ)⋯(λₙ − λ)，令 λ = 0：所有特征值的乘积等于 det A。', read='特征多项式里，还藏着两个好用的性质。把它写成拉姆达一减拉姆达，一直乘到拉姆达n减拉姆达，再令拉姆达等于零：所有特征值的乘积，等于A的行列式。'),
    dict(id='C12', pose='claude_point', sub='再比较 λⁿ⁻¹ 的系数：所有特征值的和，等于对角元之和，叫作 A 的迹，记作 tr A。', read='再比较拉姆达n减一次方的系数：所有特征值的和，等于对角元之和，叫作A的迹。'),
    dict(id='C13', pose='claude_explain', sub='例 6：A = (5 −18; 1 −1)。det A = −5 + 18 = 13，tr A = 4。特征值 2 ± 3i：和是 4，积是 4 + 9 = 13，完全对上。', read='例六：A的第一行是五、负十八，第二行是一、负一。行列式是负五加十八，等于十三，迹是四。特征值是二加减三i：和是四，积是四加九，等于十三，完全对上。'),
    dict(id='D03', mood='easy', pose='ds_proud', sub='以后算完特征值，先拿迹和行列式验一遍！', read='以后算完特征值，先拿迹和行列式验一遍！'),
    dict(id='C14', pose='claude_smile', sub='好习惯。最后连回第四章：定理 6.1.1，相似矩阵有相同的特征多项式，所以有相同的特征值。', read='好习惯。最后一个定理，连回第四章：定理六点一点一，相似矩阵有相同的特征多项式，所以特征值也相同。'),
    dict(id='C15', pose='claude_explain', sub='证明一行：det(S⁻¹AS − λI) = det(S⁻¹(A − λI)S) = det S⁻¹ · det(A − λI) · det S = det(A − λI)。', read='证明只要一行：把拉姆达I写成S逆乘拉姆达I乘S，提出来，行列式拆成三个的乘积，S逆和S的行列式相互抵消，剩下A减拉姆达I的行列式。'),
    dict(id='C16', pose='claude_point', sub='例 7：T = (2 1; 0 3)，特征值一眼看出是 2 和 3。用 S = (5 3; 3 2) 造出 A = S⁻¹TS = (−1 −2; 6 6)，特征值也是 2 和 3。', read='例七：T是上三角矩阵，特征值一眼看出，是二和三。用一个可逆矩阵S，造出A等于S逆T S，第一行负一、负二，第二行六、六。它的特征值，也是二和三。'),
    dict(id='C17', pose='claude_explain', sub='几何意义：相似矩阵是同一个线性变换在不同基下的样子。特征值描述的是变换本身的伸缩，和基的选取无关。', read='几何意义：相似矩阵，是同一个线性变换在不同基下的样子。特征值描述的是变换本身的伸缩，所以和基的选取无关。'),
    dict(id='G01', pose='gpt_explain', sub='同济对照：同济写成 λ₁ + ⋯ + λₙ = a₁₁ + ⋯ + aₙₙ，λ₁λ₂⋯λₙ = ∣A∣，并推出：A 可逆，当且仅当 0 不是特征值。', read='同济对照：同济把这两条写成，特征值之和等于主对角元之和，特征值之积等于A的行列式。并且推出：A可逆，等价于零不是A的特征值。'),
    dict(id='G02', pose='gpt_point', sub='同济还常考：λ 是 A 的特征值，则 λ² 是 A² 的，φ(λ) 是 φ(A) 的；A 可逆时，1/λ 是 A⁻¹ 的特征值。', read='同济还常考：如果拉姆达是A的特征值，那么拉姆达平方是A平方的特征值，多项式phi拉姆达是phi A的特征值；A可逆的时候，拉姆达分之一是A逆的特征值。'),
    dict(id='C18', pose='claude_explain', sub='小结：特征多项式的根就是特征值，可能重复，也可能是复数。特征值之积等于行列式，之和等于迹。相似矩阵特征值相同。', read='小结：特征多项式的根，就是特征值，可能重复，也可能是复数。特征值之积等于行列式，之和等于迹。相似矩阵的特征值相同。'),
    dict(id='C19', pose='claude_point', sub='下一节：特征值的第一个大用场，解线性微分方程组。', read='下一节：特征值的第一个大用场，解线性微分方程组。'),
]



if __name__ == '__main__':
    here = Path(__file__).resolve().parent
    for l in LINES:
        l.setdefault('read', l['sub'])
        l.setdefault('mood', None)
    ids = [l['id'] for l in LINES]; assert len(ids) == len(set(ids)), '台词 id 重复'
    (here / 'script.json').write_text(json.dumps({l['id']: [l['read'], l['mood']] for l in LINES}, ensure_ascii=False, indent=1), encoding='utf-8')
    (here / 'lines.json').write_text(json.dumps(LINES, ensure_ascii=False, indent=1), encoding='utf-8')
    print(len(LINES), 'lines,', sum(len(l['read']) for l in LINES), 'chars')
